  ('folate', 'males', '>70 y', 852, null, 'RDA', 400, 320, 1000, null, array['As Dietary Folate Equivalents (DFE). See conversion factors for more details.']::text[], array['The UL for folate applies only to synthetic forms obtained from supplements, fortified foods, or a combination of the two. The UL values are expressed as micrograms of folic acid, not micrograms of DFEs.']::text[]),
  ('folate', 'females', '9–13 y', 108, 168, 'RDA', 300, 250, 600, null, array['As Dietary Folate Equivalents (DFE). See conversion factors for more details.']::text[], array['The UL for folate applies only to synthetic forms obtained from supplements, fortified foods, or a combination of the two. The UL values are expressed as micrograms of folic acid, not micrograms of DFEs.']::text[]),
  ('folate', 'females', '14–18 y', 168, 228, 'RDA', 400, 330, 800, null, array['As Dietary Folate Equivalents (DFE). See conversion factors for more details.', 'In view of evidence linking the use of supplements containing folic acid before conception and during early pregnancy with reduced risk of neural tube defects in the fetus, it is recommended that all women capable of becoming pregnant consume 400 μg of folic acid every day, in addition to intake of food folate from a varied diet.']::text[], array['The UL for folate applies only to synthetic forms obtained from supplements, fortified foods, or a combination of the two. The UL values are expressed as micrograms of folic acid, not micrograms of DFEs.']::text[]),
  ('folate', 'females', '19–30 y', 228, 372, 'RDA', 400, 320, 1000, null, array['As Dietary Folate Equivalents (DFE). See conversion factors for more details.', 'In view of evidence linking the use of supplements containing folic acid before conception and during early pregnancy with reduced risk of neural tube defects in the fetus, it is recommended that all women capable of becoming pregnant consume 400 μg of folic acid every day, in addition to intake of food folate from a varied diet.']::text[], array['The UL for folate applies only to synthetic forms obtained from supplements, fortified foods, or a combination of the two. The UL values are expressed as micrograms of folic acid, not micrograms of DFEs.']::text[]),
  ('folate', 'females', '31–50 y', 372, 612, 'RDA', 400, 320, 1000, null, array['As Dietary Folate Equivalents (DFE). See conversion factors for more details.', 'In view of evidence linking the use of supplements containing folic acid before conception and during early pregnancy with reduced risk of neural tube defects in the fetus, it is recommended that all women capable of becoming pregnant consume 400 μg of folic acid every day, in addition to intake of food folate from a varied diet.']::text[], array['The UL for folate applies only to synthetic forms obtained from supplements, fortified foods, or a combination of the two. The UL values are expressed as micrograms of folic acid, not micrograms of DFEs.']::text[]),
  ('folate', 'females', '51–70 y', 612, 852, 'RDA', 400, 320, 1000, null, array['As Dietary Folate Equivalents (DFE). See conversion factors for more details.']::text[], array['The UL for folate applies only to synthetic forms obtained from supplements, fortified foods, or a combination of the two. The UL values are expressed as micrograms of folic acid, not micrograms of DFEs.']::text[]),
  ('folate', 'females', '>70 y', 852, null, 'RDA', 400, 320, 1000, null, array['As Dietary Folate Equivalents (DFE). See conversion factors for more details.']::text[], array['The UL for folate applies only to synthetic forms obtained from supplements, fortified foods, or a combination of the two. The UL values are expressed as micrograms of folic acid, not micrograms of DFEs.']::text[]),
  ('folate', 'pregnancy', '≤18 y', 0, 228, 'RDA', 600, 520, 800, null, array['As Dietary Folate Equivalents (DFE). See conversion factors for more details.', 'It is assumed that women will continue consuming 400 μg folic acid from supplements until their pregnancy is confirmed and they enter prenatal care. The critical time for formation of the neural tube is within four weeks after conception.']::text[], array['The UL for folate applies only to synthetic forms obtained from supplements, fortified foods, or a combination of the two. The UL values are expressed as micrograms of folic acid, not micrograms of DFEs.']::text[]),
